-- Batch 28 -- Helsinki uplift + ANID addition (2026-10-28). Replay of statements
-- actually executed against project zkdguzbdopfedkffsatk. Uplifts 742 University of
-- Helsinki Scholarship Programme (rel 9 -> 10) from re-fetched official pages; adds
-- 990 Beca de Doctorado Nacional (ANID, Chile) from the fetched concurso page and the
-- official bases PDF (Resolución 433/2026, numerals 1-7 read). Chalmers 421 was only
-- re-checked (official page still 'not yet updated' for 2027) - no DB write for it.

-- 1) New official sources (collision-checked: no anid.cl URLs existed; Helsinki's
--    scholarship page already existed as source 2536 and is reused below)
INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3133, 'https://anid.cl/concursos/beca-de-doctorado-nacional-ano-academico-2027/', $$Beca de Doctorado Nacional Año Académico 2027 - concurso page | ANID (official)$$, 'anid.cl', 'scholarship', now(), true, true, now()), (3134, 'https://s3.us-east-1.amazonaws.com/documentos.anid.cl/BecasChile/2027/DoctoradoNacional/Bases_Doctorado_Nacional_2027_Lectura_Obligatoria.pdf', $$Bases Concursales Beca de Doctorado Nacional 2027 (Resolución N°433/2026) | ANID (official PDF)$$, 'documentos.anid.cl', 'scholarship', now(), true, true, now()) RETURNING id, url;

-- 2) Uplift 742 rel 9 -> 10 (real 2027 window 5-19 Jan 2027; importer minima removed;
--    EUR 18,000/'range' award normalized to NULL/'variable'; EUR 100 fee encoded)
UPDATE scholarships SET title = $$University of Helsinki Scholarship Programme (Tuition Fee Waivers)$$, provider = $$University of Helsinki$$, country = $$Finland$$, coverage_type = $$Tuition Waiver$$, amount_usd_value = 0, award_amount = NULL, award_currency = $$EUR$$, award_period = $$year$$, award_basis = $$variable$$, deadline = $$One annual application period on Studyinfo: for studies starting in autumn 2027 it runs 5-19 January 2027, and the tuition-fee-waiver request is made on the same application form as the master's application - so 19 January 2027 is also the scholarship close. The waiver result arrives with the admission results (official acceptance e-mail); if you win, you must accept the scholarship agreement for it to take effect.$$ , deadline_date = $$2027-01-19$$, deadline_type = $$fixed$$, opening_date = $$2027-01-05$$, deadline_range_start = NULL, deadline_range_end = NULL, rounds = $$[{"name": "Autumn 2027 intake", "status": "application period 2027-01-05 to 2027-01-19 on Studyinfo (waiver requested on the same form); waiver result with the admission results e-mail; accept the scholarship agreement to activate", "deadline_date": "2027-01-19"}, {"name": "Annual pattern", "status": "one intake per year: international master's applications (and the waiver request on the same form) in the first half of January for studies starting in August", "deadline_date": null}]$$, recurrence = $$annual$$, expected_opening_period = $$Early January$$, expected_deadline_period = $$Mid-January (end of the Studyinfo application period)$$, degree_levels = $$["Master's"]$$, eligible_majors = $$["All Majors"]$$, eligible_countries = $$["Students liable for tuition fees - citizens of countries outside the EU/EEA and Switzerland without exempting Finnish residence status"]$$, min_gpa = NULL, min_ielts = NULL, financial_need_based = false, merit_based = true, description = $$The University of Helsinki's scholarship programme for excellent tuition-fee-liable students from outside the EU/EEA and Switzerland entering an English-taught Master's programme (fetched official tuition-fees-and-scholarship-programme page and master's application pages, 2026-10-28). It consists of tuition fee waivers of 50% or 100% - and the university is unusually blunt that only a very limited number can be awarded, that the majority cover 50%, that some programmes award only 50% waivers depending on their scholarship policy and applicant pool, and that the programme is highly competitive. Annual fees are EUR 13,000, 15,000 or 18,000 depending on the programme (fixed for the individual student throughout the programme), so a waiver's euro value follows your programme's fee - no single amount is encoded. Duration is two years, conditional on full-time study with at least 55 ECTS per year; progress is checked after the first year. Equally explicit: the University of Helsinki does not offer scholarships to cover living expenses, so even a 100% waiver holder must fund Helsinki living costs (and satisfy the residence-permit income requirement) from other means; the university does keep a housing quota for fee-liable international degree students. The waiver is requested on the same Studyinfo form as the master's application - you choose the 50% or 100% category - during the single annual application period (autumn 2027 intake: 5-19 January 2027); each master's programme assesses the degree and scholarship applications together (previous academic performance, motivation letter, grounds in the grant application, and possibly strategic goals) and chooses its recipients; the result comes in the official acceptance e-mail, and you must accept the scholarship agreement before it takes effect. You lose the waiver if your tuition-fee liability changes, for false information, or for cheating. Two scope notes from the same fetched page: there are NO tuition fee waivers for applicants to English-language bachelor's degrees (only a EUR 1,000 Dean's award for second/third-year performance), and graduates of a UH English-language bachelor's continuing to a linked master's get an automatic-consideration waiver by GPA (3.8/5 -> 100%; 3.4-3.7/5 -> 50%, with 55 credits in year one to continue it) - an internal pathway, not the open competition. The former national 'Finland Scholarship' relocation grant is not listed on the current page - do not count on it.$$ , requirements = $$From the fetched University of Helsinki pages. Eligibility (all must hold): you are eligible for the Master's programme at the University of Helsinki; you are liable for tuition fees (citizen of a non-EU/EEA country without Finnish permanent-residence status - liability is checked against residence-permit history); you meet the requirements for a Finnish entry visa and residence permit; and you have excellent results in your previous studies that you can prove in the application. Apply on Studyinfo during the application period (autumn 2027: 5-19 January 2027), paying the national EUR 100 application fee for non-EU/EEA applicants (since 1 January 2025; one fee covers all same-term applications; no fee waiver exists), and request the tuition fee waiver (50% or 100% category) on the same application form with all required attachments. Selection is by overall academic assessment by the master's programme (previous performance, motivation letter, grounds in the scholarship application; strategic goals may count); the result arrives in the acceptance e-mail and a scholarship agreement must be accepted. To keep a waiver: study full time and earn at least 55 ECTS per year (checked after year one); it ends if your fee-liability status changes. Living costs are never covered - arrange them separately. No minimum GPA and no scholarship-specific English score are published for the open competition (programme admission requirements apply), so none are encoded - the earlier stored 3.3 GPA / 6.5 IELTS figures were importer leftovers and have been removed.$$ , website_url = $$https://www.helsinki.fi/en/admissions-and-education/apply-bachelors-and-masters-programmes/tuition-fees-and-scholarship-programme$$, source_url = $$https://www.helsinki.fi/en/admissions-and-education/apply-bachelors-and-masters-programmes/tuition-fees-and-scholarship-programme$$, application_url = $$https://www.studyinfo.fi/$$, funding_type = $$Merit-based tuition fee waiver (50% or 100% of the programme tuition fee)$$, tuition_coverage = $$50% or 100% of the annual tuition fee (EUR 13,000 / 15,000 / 18,000 by programme, fixed for the student) for two years, conditional on at least 55 ECTS per year; most waivers awarded are 50%. Living expenses are explicitly not covered.$$ , living_allowance = NULL, travel_allowance = NULL, accommodation = NULL, application_fee = 100, english_requirements = $$The waiver sets no separate English score; the English requirement of the chosen master's programme applies (all applicants must prove language skills for admission).$$ , required_documents = $$["Master's application through Studyinfo during the annual window (autumn 2027: 5-19 January 2027) with the tuition-fee-waiver request (50% or 100% category) on the same form", "National EUR 100 application fee for non-EU/EEA applicants (paid via Studyinfo; no fee waiver available)", "Bachelor's degree certificate and transcripts proving excellent previous results, plus the programme's required attachments", "Motivation letter and the grounds stated for the waiver (both feed the programme's overall academic assessment)", "Proof of English proficiency as the programme requires; documents proving fee-liability status where relevant"]$$, application_status = $$upcoming$$, verification_status = $$verified$$, source_reliability = 10, is_active = true, university_id = 194, notes = $$BATCH 28 UPLIFT rel 9 -> 10 (2026-10-28): Helsinki tuition-fees-and-scholarship-programme page and 'Apply to International master's programmes' page re-fetched first-hand. Repairs vs the 2026-10-25 verification: genuine 2027 window encoded (application period 5-19 January 2027; waiver on the same form -> deadline_date 2027-01-19/'fixed', opening 2027-01-05, status 'upcoming', rounds added) replacing deadline_type 'annual'/no-date/'not_announced'; importer minima min_gpa 3.3 / min_ielts 6.5 removed (nothing published; contradicted the row's own text); award EUR 18,000/'range' (which encoded the most expensive programme's fee as if it were the award) normalized to NULL EUR/'year'/'variable' per the Nordic waiver-cluster convention; application_fee set to the fetched national EUR 100; accommodation empty string nulled; the third-party 'Finland Scholarship + EUR 5,000 relocation' hedge dropped (not on the current official page); added from fetch: no waivers for English bachelor's applicants (EUR 1,000 Dean's award only), internal UH-bachelor-to-master GPA pathway (3.8/5 -> 100%, 3.4-3.7/5 -> 50%; kept textual, min_gpa stays NULL), loss of waiver on fee-liability change/false info/cheating, scholarship-agreement acceptance step, programme-level variation in waiver policy, housing quota note. Existing source 2536 linked (record previously had no source link). us 182 resynced (availability 'Yes'->'available'; valued_aspect artefact fixed).$$ , last_verified_at = now(), last_updated_at = now() WHERE id = 742 RETURNING id, source_reliability;

-- 3) Source link for 742 (reuses pre-existing source 2536)
INSERT INTO scholarship_sources (scholarship_id, source_id) VALUES (742, 2536) RETURNING scholarship_id, source_id;

-- 4) university_scholarships sync for 742
UPDATE university_scholarships SET university_id = 194, scholarship_name = $$University of Helsinki Scholarship Programme (Tuition Fee Waivers)$$, availability_status = $$available$$, funding_type = $$Merit-based tuition fee waiver$$, valued_aspect = $$Overall academic assessment by the master programme: previous academic performance, motivation letter and grounds stated in the waiver application$$, eligibility_notes = $$Verified 2026-10-25 and uplifted 2026-10-28 from the official University of Helsinki tuition fees and scholarship programme page and master application pages. Master level only (no waivers for English-language bachelor applicants). Waivers of 50% or 100% of the EUR 13,000-18,000 annual fee; only a very limited number awarded, majority 50%, some programmes award only 50%. Two years, at least 55 ECTS a year, progress checked after year one; lost if fee-liability status changes. Living costs are explicitly not funded (housing quota exists for fee-liable internationals). Apply on Studyinfo during the annual window - autumn 2027: 5-19 January 2027 - requesting the waiver on the same form (choose 50% or 100% category); EUR 100 national application fee for non-EU/EEA applicants; result in the acceptance e-mail; scholarship agreement must be accepted. Internal pathway: UH English bachelor graduates continuing to a linked master get 100% waiver at GPA 3.8/5 or 50% at 3.4-3.7/5.$$ , official_url = $$https://www.helsinki.fi/en/admissions-and-education/apply-bachelors-and-masters-programmes/tuition-fees-and-scholarship-programme$$, verification_status = $$verified$$, last_verified_at = now(), scholarship_id = 742 WHERE id = 182 RETURNING id;

-- 5) New record 990 (first ANID record; 2027 competition OPEN at insertion)
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES (990, $$Beca de Doctorado Nacional (ANID National Doctoral Scholarship)$$, $$Agencia Nacional de Investigación y Desarrollo (ANID) - Government of Chile$$, $$Chile$$, $$Full Tuition + Stipend$$, 0, $$The 2027 academic-year competition is OPEN: applications and recommendation letters close on Friday 27 November 2026 at 13:00 (continental Chile time) in ANID's online system (SPL); results (fallo) are expected in January 2027; studies must start by 31 August 2027. The call opened on 9 October 2026.$$ , $$["PhD"]$$, $$["All Majors"]$$, NULL, NULL, false, true, $$Chile's national doctoral scholarship, run by the state research agency ANID under bases approved by Resolución N°433/2026 (concurso page and the official bases PDF fetched 2026-10-28). It finances doctorates in all areas of knowledge in CNA-accredited programmes at Chilean universities, for up to four years counted from the start of the programme (annual renewal on accredited progress), plus - where applicable - up to six further months of maintenance to write the thesis. The point of greatest interest here: the bases state twice that Chilean AND foreign persons may apply, "con o sin permanencia definitiva en Chile" - with or without permanent residence in Chile - so an applicant from Uzbekistan competes on the same terms, provided they are applying to, admitted to, or already a regular student in an accredited Chilean doctorate and start by 31 August 2027. Benefits (per numeral 6 of the bases, amounts set by Decreto Supremo 335/2010 and IPC-indexed each year; the list is exhaustive): a maintenance assignment of up to CLP 7,800,000 per year paid in monthly instalments; a tuition/enrolment (arancel y matrícula) assignment of up to CLP 2,700,000 per year paid against invoice directly to the university (a cap - any excess fee is yours); health coverage up to CLP 407,880 per year; 5% of the monthly maintenance per child under 18; and a pregnancy pre/post-natal maintenance extension of up to six months. Complementary benefits (thesis-writing extension, co-tutelle and research-stay support) exist under Anexo 1/2 subject to committee evaluation. Scale: this 2027 call finances a maximum of about 1,000 scholarships (final number set by the cut-off score). It is a scored competition - a parametrized score from your undergraduate grades/ranking (separate resolutions fix the conversion) plus committee evaluation of the application - and ANID publishes score simulators and historical results panels so you can gauge your chances before applying. The OAS installation grant of US$1,200 mentioned on the concurso page is only for awardees from OAS member states and does not apply to Uzbekistan. Practical realities: the whole process runs in Spanish through the SPL online system (some forms and manuals are also published in English), benefits are paid into a Chilean bank account held solely by the becario, and the 2027 bases newly require a recent Tesorería General certificate of no overdue CAE student-loan debt before the scholarship agreement (convenio) can be signed.$$ , $$From the fetched 2027 bases (numeral 4) and concurso page. Who may apply: Chileans or foreigners, with or without permanent residence in Chile, who (1) hold a Licenciado degree, professional title, or foreign equivalent (the bases name Bachelor/Diploma studies abroad; ANID decides equivalence - candidates in the final administrative stage of a Chilean degree may apply but must present the degree before the convenio deadline); (2) prove academic excellence by an undergraduate final average of at least 5.0 on Chile's 1-7 scale (or its converted equivalent) OR a place in the top 30% of their undergraduate graduation ranking - both the grades certificate and the ranking certificate (or the official no-ranking certificate) must be filed regardless, because both feed the parametrized score; (3) are formally applying to, admitted to, or a regular student in a doctoral programme accredited by the CNA (Ley 20.129) at a Chilean university - the programme must be accredited at the application close and the certifying letter must use the programme's exact CNA-registered name; and (4) start their studies by 31 August 2027 at the latest. Incompatibilities (numeral 5): no other public-sector scholarship for the same programme or degree; no previous public funding for the same or a higher degree (narrow exceptions); no outstanding becario debts with public institutions at convenio signing; and anyone registered in Chile's national alimony-debtor registry is inadmissible (checked electronically at application and award). Benefits accrue only from the convenio/adjudication dates, are proportional to actual funded study time, end at the degree exam (amounts paid after it must be returned), and require a Chilean bank account in the becario's sole name (BancoEstado Cuenta RUT etc.). Applications and recommendation letters close 27 November 2026 at 13:00 continental Chile time; no application fee is stated in the fetched bases. The Chilean 5.0/7.0 floor is scale-specific, so it is recorded here in text, not as a generic min_gpa.$$ , $$https://anid.cl/concursos/beca-de-doctorado-nacional-ano-academico-2027/$$, $$["All - Chileans and foreigners, with or without permanent residence in Chile; the doctorate must be a CNA-accredited programme at a Chilean university"]$$, $$Maintenance stipend up to CLP 7,800,000/year (monthly instalments) + tuition/enrolment assignment up to CLP 2,700,000/year paid to the university + health coverage up to CLP 407,880/year - all IPC-indexed, up to 4 years$$, $$Annual assignment toward arancel and matrícula of up to CLP 2,700,000 (IPC-indexed), paid against invoice directly to the university; it is a cap, so fees above it remain the student's. Maintenance (up to CLP 7,800,000/year in monthly instalments) and health coverage are separate benefits.$$ , NULL, NULL, NULL, NULL, $$No English-test requirement appears in the fetched bases; the competition and most Chilean doctorates operate in Spanish (ANID publishes some forms and manuals in English). Check your programme's language of instruction and any programme-level language rules.$$ , $$["Licenciado / professional title, or foreign undergraduate equivalent (e.g. bachelor's degree) - or, for Chilean degrees only, certificate of final-stage processing with the degree due before the convenio deadline", "Undergraduate grade-average certificate in ANID format (Formulario N°1; bases 8.9.5) evidencing the 5.0/7.0-equivalent floor - mandatory even when qualifying via ranking", "Undergraduate graduation-ranking certificate stating position and cohort size (bases 8.9.6), or the official no-ranking certificate (available in English) if the home institution issues no ranking", "Letter from the doctoral programme or ANID form certifying formal application / admission / regular-student status in a CNA-accredited doctorate, using the programme's exact CNA-registered name (bases 8.9.7)", "Online application in ANID's SPL system with CV de postulación and recommendation letters, all by the same close (27 November 2026, 13:00 continental Chile)"]$$, $$https://anid.cl/concursos/beca-de-doctorado-nacional-ano-academico-2027/$$, $$2026-10-09$$, $$2026-11-27$$, $$fixed$$, NULL, NULL, $$[{"name": "Beca de Doctorado Nacional 2027", "status": "OPEN: opened 2026-10-09; applications and recommendation letters close 2026-11-27 13:00 (continental Chile); results (fallo) expected January 2027; studies must start by 2027-08-31; up to ~1,000 scholarships foreseen", "deadline_date": "2026-11-27"}, {"name": "Annual pattern", "status": "calls open in September-October and close in November (2023: 9 Nov-14 Dec 2022; 2024: 28 Sep-15 Nov 2023; 2025: 25 Sep-15 Nov 2024), decisions in January-February", "deadline_date": null}]$$, $$annual$$, $$September-October$$, $$Mid/late November (13:00 continental Chile)$$, $$open$$, now(), now(), $$verified$$, 10, $$https://anid.cl/concursos/beca-de-doctorado-nacional-ano-academico-2027/$$, $$BATCH 28 NEW RECORD (2026-10-28): first ANID record in the catalogue; flagged as a candidate in Pass 121 and now verified first-hand - concurso page (new source 3133) plus the official bases PDF, Resolución 433/2026 (new source 3134), numerals 1-7 read (objective, duration, requirements, incompatibilities, benefits). Foreigner clause fetched verbatim in both (bases 1 and 4.1: 'personas naturales chilenas o extranjeras, con o sin permanencia definitiva en Chile'). CLP caps from 6.1.1 (manutención $7.800.000/yr), 6.1.2 (arancel/matrícula $2.700.000/yr paid to the university), 6.1.4 (salud $407.880/yr) are recorded in text with award NULL CLP/'year'/'variable' (capped, IPC-indexed, multi-component); monthly arithmetic is not encoded. Up-to-1.000-becas figure and call dates from the concurso page; annual pattern from the page's concursos-anteriores cards. Complementary-benefit categories (thesis extension, cotutela/pasantía) are named from the bases TOC/3.6/7.1 only - Anexo amounts not read, none asserted. OAS US$1,200 extra is OAS-members-only (Uzbekistan not applicable). 5.0/7.0 floor kept textual (Chilean scale), min_gpa NULL. university_id NULL (national agency covering all Chilean universities) - no university_scholarships row. Status 'open' as of insertion (closes 2026-11-27); will need a status refresh after that date in a later cycle pass.$$ , true, NULL, NULL, $$CLP$$, $$year$$, $$variable$$) RETURNING id, title;

